{"tool":"write_file","args":{"path":"inventory/reports.py","content":"from datetime import date
from collections import Counter
from typing import List

from .models import Loan
from .storage import Storage

class Reports:
    def __init__(self, storage: Storage):
        self.storage = storage

    def overdue_isbns(self, as_of: str) -> List[str]:
        as_of_dt = date.fromisoformat(as_of)
        overdue = [l.isbn for l in self.storage.list_loans() if date.fromisoformat(l.due_date) < as_of_dt]
        return sorted(set(overdue))

    def total_fees_per_member(self) -> List[tuple]:
        fees = self.storage.list_return_fees()
        totals = Counter()
        for record in fees:
            totals[record["member_id"]] += record["fee"]
        return sorted(totals.items(), key=lambda x: x[0])

    def most_borrowed_isbns(self, top_n: int = 5) -> List[tuple]:
        history = self.storage.list_borrow_history()
        counter = Counter()
        for record in history:
            counter[record["isbn"]] += 1
        return counter.most_common(top_n)
